import logging
import sys
import unittest

def prepare(level: int) -> int:
    root = logging.getLogger("")
    assert not root.handlers
    root.setLevel(level)
    return root.level

class NativeCase:

    def assertIsNotNone(self, item: logging.Formatter | None) -> None:
        if item is None:
            raise AssertionError("unexpectedly None")

    def assertIs(self, left: logging.Handler | logging.Formatter | None,
                 right: logging.Handler | logging.Formatter | None) -> None:
        if left is not right:
            raise AssertionError("different objects")

    original_logging_level: int

    def __init__(self) -> None:
        self.original_logging_level = prepare(30)

