stream_assertion_controls.source:
import io
import logging
import typing

class Assertions:

    def assertIs(self, first, second: typing.TextIO) -> None:
        if first is not second:
            raise AssertionError("different stream objects")

    def assertIsNone(self, value) -> None:
        if value is not None:
            raise AssertionError("expected unchanged stream")

def exercise() -> None:
    checks = Assertions()
    first = io.StringIO()
    second = io.StringIO()
    handler = logging.StreamHandler(first)
    old = handler.setStream(second)
    checks.assertIs(old, first)
    checks.assertIsNone(handler.setStream(second))
    print("original stream and unchanged result accepted")
    try:
        checks.assertIs(old, second)
    except AssertionError as error:
        print(str(error))
    try:
        checks.assertIsNone(old)
    except AssertionError as error:
        print(str(error))

exercise()
